// ============================================================================
// TYPES
// ============================================================================

export type ExtendedCamSource =
  | "powermill"
  | "catia"
  | "cimatron"
  | "tebis"
  | "worknc"
  | "camworks"
  | "bobcad"
  | "edgecam"
  | "topsolid"
  | "sprutcam"
  | "mazatrol"
  | "macro_programming"
  | "vericut";

export type ExtCamGeometryType =
  | "pocket_2d" | "contour_2d" | "face" | "slot" | "chamfer"
  | "freeform_3d" | "steep_wall" | "flat_area" | "groove" | "rib"
  | "corner" | "turning_external" | "turning_internal" | "turning_groove"
  | "thread" | "hole" | "bore" | "impeller_blade" | "port_inlet"
  | "ruled_surface" | "trimming_edge" | "undercut" | "turbine_blade"
  | "mold_core" | "mold_cavity" | "electrode" | "tire_mold"
  | "blisk" | "medical_implant" | "thin_wall" | "deep_cavity";

export type ExtCamOperationGoal =
  | "roughing" | "finishing" | "semi_finishing" | "rest_machining"
  | "drilling" | "adaptive_clearing" | "deburring"
  | "conversational" | "macro_cycle" | "simulation_optimize";

export interface ExtCamStrategyInput {
  camSystem: ExtendedCamSource;
  geometryType: ExtCamGeometryType;
  operationGoal: ExtCamOperationGoal;
  materialGroup?: string;
  toolDiameterMm?: number;
  wallAngleDeg?: number;
  hasPreviousRoughing?: boolean;
  axisCount?: 3 | 4 | 5;
}

export interface ExtCamStrategyResult {
  strategyName: string;
  nativeCycleName: string;
  camSystem: ExtendedCamSource;
  description: string;
  suggestedStepdown: number | null;
  suggestedStepover: number | null;
  cuttingMode: "climb" | "conventional" | "zigzag";
  warnings: string[];
  confidence: number;
  equivalentIntents: string[];
  source: string;
}

interface ExtStrategyEntry {
  nativeCycle: string;
  description: string;
  stepdownFactor: number | null;
  stepoverFactor: number | null;
  cuttingMode: "climb" | "conventional" | "zigzag";
  suitableFor: { geometry: ExtCamGeometryType[]; goal: ExtCamOperationGoal[] };
  priority: number;
  equivalentIntents: string[];
  materialNotes?: Record<string, string>;
}

