// ============================================================================
// ENGINE CLASS
// ============================================================================

export interface ExtMultiCamStats {
  totalStrategies: number;
  bySystem: Record<ExtendedCamSource, number>;
  calculations: number;
}

export class MultiCamStrategyEngineExt {
  private calculations = 0;

  /**
   * Recommend the best strategy for a given extended CAM system.
   */
  recommend(input: ExtCamStrategyInput): ExtCamStrategyResult {
    this.calculations++;
    const strategies = EXT_STRATEGY_MAP[input.camSystem];
    if (!strategies) {
      return this.notFound(input, `Unknown CAM system: ${input.camSystem}`);
    }

    const candidates = strategies.filter(
      (s) =>
        s.suitableFor.geometry.includes(input.geometryType as any) &&
        s.suitableFor.goal.includes(input.operationGoal as any)
    );

    if (candidates.length === 0) {
      return this.notFound(input, `No strategy for ${input.geometryType}/${input.operationGoal} in ${input.camSystem}`);
    }

    candidates.sort((a, b) => b.priority - a.priority);
    const best = candidates[0];

    const warnings: string[] = [];
    if (input.materialGroup === "S" && input.operationGoal === "roughing") {
      warnings.push("Superalloy roughing: reduce speed 30-40%, use through-spindle coolant");
    }
    if (input.materialGroup === "H" && best.stepdownFactor && best.stepdownFactor > 1.5) {
      warnings.push("Hardened material: reduce depth of cut to 50%");
    }
    if (input.axisCount && input.axisCount < 5 && best.equivalentIntents.some((i) => i.startsWith("5axis"))) {
      warnings.push(`Strategy requires 5-axis but machine has ${input.axisCount} axes`);
    }

    let stepdown = best.stepdownFactor;
    let stepover = best.stepoverFactor;
    if (input.materialGroup === "S" || input.materialGroup === "H") {
      if (stepdown !== null) stepdown = Math.min(stepdown, 1.0);
      if (stepover !== null) stepover = Math.min(stepover, stepover * 0.7);
    }

    return {
      strategyName: best.nativeCycle,
      nativeCycleName: best.nativeCycle,
      camSystem: input.camSystem,
      description: best.description,
      suggestedStepdown: stepdown,
      suggestedStepover: stepover,
      cuttingMode: best.cuttingMode,
      warnings,
      confidence: this.calcConfidence(best, input),
      equivalentIntents: best.equivalentIntents,
      source: `multicam_ext:${input.camSystem}`,
    };
  }

  /**
   * List all strategies for a given extended CAM system.
   */
  listStrategies(camSystem: ExtendedCamSource): ExtCamStrategyResult[] {
    const strategies = EXT_STRATEGY_MAP[camSystem];
    if (!strategies) return [];
    return strategies.map((s) => ({
      strategyName: s.nativeCycle,
      nativeCycleName: s.nativeCycle,
      camSystem,
      description: s.description,
      suggestedStepdown: s.stepdownFactor,
      suggestedStepover: s.stepoverFactor,
      cuttingMode: s.cuttingMode,
      warnings: [],
      confidence: 1.0,
      equivalentIntents: s.equivalentIntents,
      source: `multicam_ext:${camSystem}`,
    }));
  }

  /**
   * Get flagship strategy for an extended CAM system.
   */
  getFlagship(camSystem: ExtendedCamSource): ExtCamStrategyResult | null {
    const name = EXT_FLAGSHIP_STRATEGIES[camSystem];
    if (!name) return null;
    const strategies = EXT_STRATEGY_MAP[camSystem];
    const entry = strategies?.find((s) => s.nativeCycle === name);
    if (!entry) return null;
    return {
      strategyName: entry.nativeCycle,
      nativeCycleName: entry.nativeCycle,
      camSystem,
      description: entry.description,
      suggestedStepdown: entry.stepdownFactor,
      suggestedStepover: entry.stepoverFactor,
      cuttingMode: entry.cuttingMode,
      warnings: [],
      confidence: 1.0,
      equivalentIntents: entry.equivalentIntents,
      source: `multicam_ext:${camSystem}`,
    };
  }

  /**
   * Compare across all extended CAM systems.
   */
  compareAcrossSystems(
    geometryType: ExtCamGeometryType,
    operationGoal: ExtCamOperationGoal
  ): Record<ExtendedCamSource, ExtCamStrategyResult | null> {
    const result: Record<string, ExtCamStrategyResult | null> = {};
    for (const sys of Object.keys(EXT_STRATEGY_MAP) as ExtendedCamSource[]) {
      const rec = this.recommend({ camSystem: sys, geometryType, operationGoal });
      result[sys] = rec.confidence > 0 ? rec : null;
    }
    return result as Record<ExtendedCamSource, ExtCamStrategyResult | null>;
  }

  /**
   * Get portability intents for a native cycle.
   */
  getPortabilityIntents(camSystem: ExtendedCamSource, nativeCycleName: string): string[] {
    const strategies = EXT_STRATEGY_MAP[camSystem];
    if (!strategies) return [];
    const entry = strategies.find((s) => s.nativeCycle === nativeCycleName);
    return entry?.equivalentIntents ?? [];
  }

  /**
   * Get stats.
   */
  stats(): ExtMultiCamStats {
    const bySystem: Record<string, number> = {};
    let total = 0;
    for (const [sys, strats] of Object.entries(EXT_STRATEGY_MAP)) {
      bySystem[sys] = strats.length;
      total += strats.length;
    }
    return {
      totalStrategies: total,
      bySystem: bySystem as Record<ExtendedCamSource, number>,
      calculations: this.calculations,
    };
  }

  /**
   * List all supported extended CAM systems.
   */
  listSystems(): ExtendedCamSource[] {
    return Object.keys(EXT_STRATEGY_MAP) as ExtendedCamSource[];
  }

  /**
   * Search strategies across all systems by keyword.
   */
  search(query: string, limit = 20): ExtCamStrategyResult[] {
    const q = query.toLowerCase();
    const results: ExtCamStrategyResult[] = [];
    for (const [sys, strats] of Object.entries(EXT_STRATEGY_MAP)) {
      for (const s of strats) {
        if (results.length >= limit) break;
        if (
          s.nativeCycle.toLowerCase().includes(q) ||
          s.description.toLowerCase().includes(q) ||
          s.equivalentIntents.some((i) => i.includes(q))
        ) {
          results.push({
            strategyName: s.nativeCycle,
            nativeCycleName: s.nativeCycle,
            camSystem: sys as ExtendedCamSource,
            description: s.description,
            suggestedStepdown: s.stepdownFactor,
            suggestedStepover: s.stepoverFactor,
            cuttingMode: s.cuttingMode,
            warnings: [],
            confidence: 1.0,
            equivalentIntents: s.equivalentIntents,
            source: `multicam_ext:${sys}`,
          });
        }
      }
    }
    return results;
  }

  // ── Private ─────────────────────────────────────────────────────────────

  private calcConfidence(entry: ExtStrategyEntry, input: ExtCamStrategyInput): number {
    let c = 0.8;
    if (input.materialGroup) c += 0.05;
    if (input.toolDiameterMm) c += 0.05;
    if (entry.priority >= 12) c += 0.05;
    if (entry.materialNotes && input.materialGroup && entry.materialNotes[input.materialGroup]) c += 0.05;
    return Math.min(c, 1.0);
  }

  private notFound(input: ExtCamStrategyInput, msg: string): ExtCamStrategyResult {
    return {
      strategyName: "none",
      nativeCycleName: "none",
      camSystem: input.camSystem,
      description: msg,
      suggestedStepdown: null,
      suggestedStepover: null,
      cuttingMode: "climb",
      warnings: [msg],
      confidence: 0,
      equivalentIntents: [],
      source: `multicam_ext:${input.camSystem}`,
    };
  }
}

// ── Singleton ───────────────────────────────────────────────────────────────
export const multiCamStrategyEngineExt = new MultiCamStrategyEngineExt();
